func ByAgentToolResultBlobs(term sql.OrderTerm, terms ...sql.OrderTerm) OrderOption {
	return func(s *sql.Selector) {
		sqlgraph.OrderByNeighborTerms(s, newAgentToolResultBlobsStep(), append([]sql.OrderTerm{term}, terms...)...)
	}
}
